DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261020183354_Inicial') THEN
    CREATE TABLE "ANALISE" (
        "ID_ANALISE" integer GENERATED BY DEFAULT AS IDENTITY,
        "ID_DEPLOY" integer NOT NULL,
        "DSC_FERRAMENTA" character varying(30) NOT NULL,
        "DSC_TIPO_ANALISE" character varying(10) NOT NULL,
        "COD_PIPELINE" integer NOT NULL,
        "DSC_TAG" text NOT NULL,
        "COD_SCAN" character varying(50),
        "DSC_URL_ALVO" character varying(500),
        "IND_STATUS" character varying(15) NOT NULL,
        "NUM_VULNERABILIDADE_CRITICA" integer NOT NULL,
        "NUM_VULNERABILIDADE_ALTA" integer NOT NULL,
        "NUM_VULNERABILIDADE_MEDIA" integer NOT NULL,
        "NUM_VULNERABILIDADE_BAIXA" integer NOT NULL,
        CONSTRAINT "PK_ANALISE" PRIMARY KEY ("ID_ANALISE"),
        CONSTRAINT "FK_ANALISE_DEPLOY_ID_DEPLOY" FOREIGN KEY ("ID_DEPLOY") REFERENCES "DEPLOY" ("ID_DEPLOY") ON DELETE CASCADE
    );
    END IF;
END $EF$;

