        "IND_OWASP_VULNERABILIDADE" character varying(200),
        "IND_CVE_VULNERABILIDADE" character varying(200),
        "DSC_TITULO_VULNERABILIDADE" character varying(200),
        "CLB_VULNERABILIDADE" text,
        "CLB_PACOTE_CORRECAO" character varying(800),
        "DSC_LINHA_VULNERABILIDADE" text,
        CONSTRAINT "PK_ARTEFATO" PRIMARY KEY ("ID_ARTEFATO"),
        CONSTRAINT "FK_ARTEFATO_ANALISE_ID_ANALISE" FOREIGN KEY ("ID_ANALISE") REFERENCES "ANALISE" ("ID_ANALISE") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261020183354_Inicial') THEN
    CREATE INDEX "IX_ANALISE_ID_DEPLOY" ON "ANALISE" ("ID_DEPLOY");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261020183354_Inicial') THEN
    CREATE UNIQUE INDEX "UK_ANALISE_URL_EXECUTANDO" ON "ANALISE" ("DSC_URL_ALVO") WHERE "DSC_TIPO_ANALISE" = 'DAST' AND "IND_STATUS" = 'EXECUTANDO';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261020183354_Inicial') THEN
